 void rules(int id,int page){String[] words=Game.RULES[id].split(" ");ArrayList<String> pages=new ArrayList<>();StringBuilder current=new StringBuilder();for(String word:words){if(current.length()+word.length()>330){pages.add(current.toString());current=new StringBuilder();}current.append(word).append(' ');}pages.add(current.toString());int index=Math.max(0,Math.min(page,pages.size()-1));AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle(Game.NAMES[id]+" · "+(index+1)+"/"+pages.size()).setMessage(pages.get(index)).setNegativeButton("Close",null);if(index+1<pages.size())dialog.setPositiveButton("Next",(d,w)->rules(id,index+1));if(index>0)dialog.setNeutralButton("Previous",(d,w)->rules(id,index-1));dialog.show();}

