 void scheduleBot(){
  if(!solo||game==null||game.id==15||game.setup||game.winner>=0||session.equals(thinkingSession)||destroyed||!botError.isEmpty())return;
  if(game.id==13&&game.phase==1){if(!game.prepared[1-me]){game.move(1-me,-4,0,5);showSnapshot();}return;}
  if(game.turn==me)return;
  final String match=session;
  final int seq=game.seq,player=1-me,level=botLevel;
  final Game position=game.copy();
  final Bot brain=bot;
  // A guided response is authored data, not an engine request.  Keep it off
  // the Stockfish worker so an abandoned match can never hold up a lesson.
  final boolean scriptedLesson=learnMode&&openingLesson>=0&&position.id==0;
  final int lesson=scriptedLesson?openingLesson:-1;
  final int[] scripted=scriptedLesson?ChessTutor.next(position,lesson):null;
  thinkingSession=match;
  if(scripted!=null){
   handler.postDelayed(()->{
    if(match.equals(thinkingSession))thinkingSession="";
    if(destroyed)return;
    boolean sameMatch=solo&&game!=null&&session.equals(match)&&game.seq==seq&&game.turn==player&&game.winner<0;
    boolean sameLesson=learnMode&&openingLesson==lesson;
    if(sameMatch&&sameLesson){
     if(game.move(player,scripted[0],scripted[1],scripted.length>2?scripted[2]:5)){botError="";showSnapshot();}
     else{botError="The planned lesson reply could not be applied. Tap Retry bot.";renderGame();}
    }else scheduleBot();
   },350L);
   return;
  }
  worker.execute(()->{
   int[] move=null;String error="";
   try{
    move=position.id==0?getStockfish().choose(position,level):brain.choose(position,player);
    if(move==null)error="The bot returned no move.";
   }catch(Exception e){error="Engine unavailable. Tap Retry bot.";android.util.Log.e("TrailLink","Bot failed",e);}
   final int[] chosen=move;final String failure=error;
   handler.postDelayed(()->{
    if(match.equals(thinkingSession))thinkingSession="";
    if(destroyed)return;
    boolean sameMatch=solo&&game!=null&&session.equals(match)&&game.seq==seq&&game.turn==player&&game.winner<0;
    if(sameMatch){
     if(chosen!=null&&game.move(player,chosen[0],chosen[1],chosen.length>2?chosen[2]:5)){botError="";showSnapshot();}
     else{botError=failure.isEmpty()?"Invalid engine move. Tap Retry bot.":failure;renderGame();}
    }else scheduleBot();
   },position.id==9?3300:150);
  });
 }
