 void analysisDetails(String report,int page){String[] lines=report.isEmpty()?new String[]{"Analysis is still running."}:report.split("\\n");int p=Math.max(0,Math.min(lines.length-1,page));AlertDialog.Builder d=new AlertDialog.Builder(this).setTitle("Analysis · "+(p+1)+"/"+lines.length).setMessage(lines[p]).setNegativeButton("Close",null);if(p>0)d.setNeutralButton("Previous",(x,w)->analysisDetails(report,p-1));if(p+1<lines.length)d.setPositiveButton("Next",(x,w)->analysisDetails(report,p+1));d.show();}

