 void showChat(){if(!ready||local)return;unread=0;if(chatDialog!=null){chatDialog.setOnDismissListener(null);chatDialog.dismiss();}LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),dp(6),dp(16),dp(6));int pages=Math.max(1,chats.size());chatPage=Math.max(0,Math.min(chatPage,pages-1));String message=chats.isEmpty()?"Say hello. Messages stay on Bluetooth.":chats.get(chats.size()-1-chatPage);chatText=text(message,14,INK);chatText.setMaxLines(12);chatText.setAutoSizeTextTypeUniformWithConfiguration(11,14,1,android.util.TypedValue.COMPLEX_UNIT_SP);box.addView(chatText,new LinearLayout.LayoutParams(-1,dp(200)));LinearLayout nav=new LinearLayout(this);box.addView(nav);if(chatPage+1<pages)footerButton(nav,"Older",()->{chatPage++;showChat();});TextView pageLabel=text((pages-chatPage)+"/"+pages,12,MUTED);pageLabel.setGravity(Gravity.CENTER);nav.addView(pageLabel,new LinearLayout.LayoutParams(0,dp(48),1));if(chatPage>0)footerButton(nav,"Newer",()->{chatPage--;showChat();});EditText input=new EditText(this);input.setHint("Message…");input.setSingleLine(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(300)});box.addView(input);chatDialog=new AlertDialog.Builder(this).setTitle("Bluetooth chat").setView(box).setNegativeButton("Close",null).setPositiveButton("Send",null).create();chatDialog.setOnShowListener(d->chatDialog.getButton(-1).setOnClickListener(v->{String body=input.getText().toString().trim();if(!body.isEmpty()&&ready){sendChat(body);chatPage=0;input.setText("");showChat();}}));chatDialog.setOnDismissListener(d->{chatText=null;if(inGame)renderGame();else home();});chatDialog.show();}
