 void appendChat(String value,boolean incoming){chats.add(value);while(chats.size()>100)chats.remove(0);if(chatText!=null){chatText.setText(value);chatPage=0;}else if(incoming){unread++;toast("New Bluetooth message");if(inGame)renderGame();else home();}save();}

 boolean canAnalyzeChessGame(){return game!=null&&game.id==0&&game.winner>=0;}
 void beginAnalysis(){if(!canAnalyzeChessGame()||session.equals(analyzing)||!analysisError.isEmpty())return;if(!game.analysis.isEmpty()&&!game.analysis.get(0).contains(StockfishEngine.NAME)){game.analysis.clear();game.analysisBest.clear();}if(game.analysis.size()>=game.chessMoves.size())return;final Game match=game.copy();final String token=session;analyzing=token;worker.execute(()->{try{for(int ply=match.analysis.size();ply<match.chessMoves.size();ply++){if(destroyed||!token.equals(analyzing))return;final int index=ply;final StockfishEngine.Review result=getStockfish().analyze(match,ply);handler.post(()->{if(game==null||!token.equals(session)||destroyed)return;if(game.analysis.size()==index){game.analysis.add(result.text);game.analysisBest.add(result.best);}if(!local&&host&&ready)send(obj("type","analysis","session",session,"index",index+1,"result",result.text,"best",array(result.best)));save();if(reviewing)review();});}}catch(Exception e){android.util.Log.e("TrailLink","Stockfish analysis failed",e);handler.post(()->{if(token.equals(session)&&!destroyed){analysisError="Stockfish analysis paused; return to the result and tap Retry analysis.";toast(analysisError);if(reviewing)review();else renderGame();}});}finally{handler.post(()->{if(token.equals(analyzing))analyzing="";});}});}


