 void save(){getSharedPreferences("coach",0).edit().putString("session",session).putBoolean("learn",learnMode).putInt("lesson",openingLesson).apply();try{java.io.File tmp=new java.io.File(getFilesDir(),"match.tmp");try(java.io.ObjectOutputStream out=new java.io.ObjectOutputStream(new java.io.FileOutputStream(tmp))){out.writeInt(3);out.writeBoolean(local);out.writeBoolean(host);out.writeBoolean(solo);out.writeInt(me);out.writeInt(botLevel);out.writeUTF(session);out.writeUTF(savedPeer);out.writeObject(game);out.writeObject(bot);out.writeObject(state==null?"":state.toString());out.writeObject(chats);out.writeObject(reviewBoards.toString());out.writeObject(reviewNotes.toString());out.writeObject(analysisNotes.toString());out.writeObject(reviewMoves.toString());out.writeObject(reviewBest.toString());}java.nio.file.Files.move(tmp.toPath(),new java.io.File(getFilesDir(),"match.bin").toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}catch(Exception e){android.util.Log.e("TrailLink","Could not save match",e);toast("Could not save match. Keep the app open.");}}
 @SuppressWarnings("unchecked") void restore(){java.io.File file=new java.io.File(getFilesDir(),"match.bin");if(!file.exists())return;try(java.io.ObjectInputStream in=new java.io.ObjectInputStream(new java.io.FileInputStream(file))){if(in.readInt()!=3){toast("Version 3 uses new match rules. Your old match cannot be resumed.");return;}local=in.readBoolean();host=in.readBoolean();solo=in.readBoolean();me=in.readInt();botLevel=in.readInt();session=in.readUTF();savedPeer=in.readUTF();game=(Game)in.readObject();bot=(Bot)in.readObject();String json=(String)in.readObject();state=json.isEmpty()?null:new JSONObject(json);passSwap=state!=null&&state.optBoolean("passSwap");chats=(ArrayList<String>)in.readObject();reviewBoards=new JSONArray((String)in.readObject());reviewNotes=new JSONArray((String)in.readObject());analysisNotes=new JSONArray((String)in.readObject());reviewMoves=new JSONArray((String)in.readObject());reviewBest=new JSONArray((String)in.readObject());android.content.SharedPreferences coachPrefs=getSharedPreferences("coach",0);learnMode=solo&&game!=null&&game.id==0&&session.equals(coachPrefs.getString("session",""))&&coachPrefs.getBoolean("learn",false);openingLesson=learnMode?coachPrefs.getInt("lesson",-1):-1;if(state!=null)status=local?"Saved offline match":"Saved match • reconnect to resume";}catch(Exception e){game=null;state=null;session="";savedPeer="";local=solo=false;android.util.Log.e("TrailLink","Could not restore match",e);}}

 void chooseRts(){if(local&&!solo){new AlertDialog.Builder(this).setTitle("Real-time skirmish").setMessage("Rift Command needs simultaneous commanders. Play against a bot or use two Bluetooth phones.").setPositiveButton("Play bot",(d,w)->{solo=true;chooseRts();}).setNegativeButton("Cancel",null).show();return;}String[] choices={"Bastion · durable structures","Flux · faster units and training"};new AlertDialog.Builder(this).setTitle("Rift Command · choose doctrine").setItems(choices,(d,w)->{rtsDoctrine=w;new AlertDialog.Builder(this).setTitle("Choose battlefield").setItems(new String[]{"The Divide · central passage","Northfall · two fronts","Ash Basin · southern route"},(a,b)->{rtsMap=b;if(local)startGame(15);else invite(15);}).show();}).show();}
