 void showRts(){if(state==null)return;rtsCommand=Math.max(rtsCommand,state.optLong("ack"));boolean already=rtsVisible&&rtsView!=null;inGame=true;reviewing=false;gameScreen=false;rtsVisible=true;if(already){rtsView.update(state);return;}setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);getWindow().setStatusBarColor(RiftView.BG);getWindow().setNavigationBarColor(RiftView.BG);getWindow().getDecorView().setSystemUiVisibility(0);if(Build.VERSION.SDK_INT>=30)getWindow().getInsetsController().setSystemBarsAppearance(0,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);board=null;root=new LinearLayout(this);root.setOrientation(1);root.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);root.setBackgroundColor(RiftView.BG);root.setOnApplyWindowInsetsListener((v,ins)->{int l=ins.getSystemWindowInsetLeft(),t=ins.getSystemWindowInsetTop(),r=ins.getSystemWindowInsetRight(),b=ins.getSystemWindowInsetBottom();if(Build.VERSION.SDK_INT>=30){android.graphics.Insets safe=ins.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());l=safe.left;t=safe.top;r=safe.right;b=safe.bottom;}v.setPadding(l+dp(8),t,r+dp(8),b);return ins;});rtsView=new RiftView(this,state);root.addView(rtsView,new LinearLayout.LayoutParams(-1,-1));setContentView(root);root.requestApplyInsets();rtsPresence();scheduleRts();}
 void scheduleRts(){if(rtsLoopScheduled||destroyed||game==null||game.id!=15||!(local||host))return;rtsLoopScheduled=true;handler.postDelayed(()->{rtsLoopScheduled=false;if(destroyed||game==null||game.id!=15)return;if(!rtsIsPaused()&&game.rts.winner<0){game.rts.step();if(solo)game.rts.bot(1-me,botLevel);game.seq=game.rts.tick;game.winner=game.rts.winner;}if(game.rts.tick%2==0||rtsIsPaused())publishRts();if(game.winner>=0?rtsLastSave!=-2:game.rts.tick/50!=rtsLastSave){rtsLastSave=game.winner>=0?-2:game.rts.tick/50;save();}scheduleRts();},100);}
